import{_ as s,o as n,c as t,a4 as e}from"./chunks/framework.B0hSrcZ6.js";const i="/info/06-memory.webp",l="/info/06-memory-s2.webp",p="/info/06-memory-s3.webp",o="/info/06-memory-s5.webp",m=JSON.parse('{"title":"第 6 章 记忆：让 Bot 越用越懂你","description":"本章剖析 Grok Bot 的记忆机制与五类容器分层，厘清记忆与技能的边界。指导读者建立团队写入协议与防冲突规则，掌握提示词库并实现云端记忆的备份与恢复。","frontmatter":{},"headers":[],"relativePath":"part1/06-memory.md","filePath":"part1/06-memory.md","lastUpdated":1792210948000}'),r={name:"part1/06-memory.md"};function c(h,a,d,g,k,u){return n(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="第-6-章-记忆-让-bot-越用越懂你" tabindex="-1">第 6 章 记忆：让 Bot 越用越懂你 <a class="header-anchor" href="#第-6-章-记忆-让-bot-越用越懂你" aria-label="Permalink to &quot;第 6 章 记忆：让 Bot 越用越懂你&quot;">​</a></h1><p>Bot 记忆是跨会话的工作上下文。把所有聊天当记忆，容易把临时变通当规矩，甚至拿过期数据乱做决定。</p><ul><li>搞清五类容器与快慢时钟，分清记忆与技能。</li><li>团队协作定好晋升协议，<strong>变动数据实时回源核对</strong>。</li><li>用 Git 搭建备份流水线，<strong>云电脑重置也能完整还原</strong>。</li></ul><p><img src="'+i+'" alt="记忆：让 Bot 越用越懂你" width="1600" height="1013" decoding="async"></p><h2 id="_6-1-官方记忆机制-bot-究竟记住了什么" tabindex="-1">6.1 官方记忆机制：Bot 究竟记住了什么 <a class="header-anchor" href="#_6-1-官方记忆机制-bot-究竟记住了什么" aria-label="Permalink to &quot;6.1 官方记忆机制：Bot 究竟记住了什么&quot;">​</a></h2><p>Bot 记偏好、事实与摘要，见 <a href="https://cursor.com/cn/docs/grok-bot/work" target="_blank" rel="noreferrer">使用 Grok Bot</a>。</p><p><strong>别把 Bot 当数据库</strong>。</p><ul><li>变动数据留源系统，重大决策核查源头。</li><li>记错或假设过时，直接对话纠正或删除。</li><li><strong>安全与权限靠审批弹窗和 Auto-review 把关</strong>，绝不靠记忆。</li><li>长期规则首条讲清，单次任务当轮生效。</li></ul><p>点顶部名称改配置。iPhone 复制 Bot：</p><ul><li>继承：配置、技能、Routine 与头像</li><li>不继承：对话、记忆与附件</li></ul><p>后续还用建议<strong>在侧边栏设为「隐藏」</strong>，直接删会清空记录。坑点：所有 Bot 共用云电脑，删 Bot 不清文件与登录态，残留需手动进文件系统清理。</p><h2 id="_6-2-记忆分层-五类容器与快慢时钟" tabindex="-1">6.2 记忆分层：五类容器与快慢时钟 <a class="header-anchor" href="#_6-2-记忆分层-五类容器与快慢时钟" aria-label="Permalink to &quot;6.2 记忆分层：五类容器与快慢时钟&quot;">​</a></h2><p><img src="'+l+`" alt="6.2 记忆分层：五类容器与快慢时钟" width="1600" height="1013" loading="lazy" decoding="async"></p><p>数据分为共享层与专属层，见《4.6 虚拟机、记忆与备份》 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/KUggwkhqqiRyxZkwTLhcrCU2ncg" target="_blank" rel="noreferrer">fs69.md</a>。</p><p>五类容器模型见《Grok Bot Memory Engineering: How One Agent Learns With a Team｜rari》 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/FW0Ww6c4nivdMgkK7YncWmBent0" target="_blank" rel="noreferrer">fs57.md</a>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>实时数据源 (LIVE SOURCE)  -&gt; 存在 Linear、Datadog、CRM、代码库或知识库里的当前事实</span></span>
<span class="line"><span>团队技能 (TEAM SKILL)     -&gt; 由 Bot 所有者维护的标准化、可重复执行的操作流程</span></span>
<span class="line"><span>团队记忆 (TEAM MEMORY)    -&gt; 经过核准的全员共享决策与稳定业务定义</span></span>
<span class="line"><span>私人便签 (PRIVATE NOTE)   -&gt; 个人专属偏好与单人工作上下文</span></span>
<span class="line"><span>任务状态 (TASK STATE)     -&gt; 当前正在执行的任务进度与临时上下文</span></span></code></pre></div><p><strong>容器不能混用</strong>。日志随跑随丢，流程入技能，习惯记便签，P0 定义才进团队记忆。</p><p>防污染用<strong>快慢时钟分流</strong>。</p><ul><li>慢时钟：风格与定义以月年计，写入记忆。</li><li>快时钟：余额随时变，<strong>行动前必须回源查询</strong>。</li></ul><p>密码与 Token 绝不入记忆，文档只存指针。实时状态查 API，别凭记忆放行权限。</p><h2 id="_6-3-记忆与技能的边界-知道什么与怎么做" tabindex="-1">6.3 记忆与技能的边界：知道什么与怎么做 <a class="header-anchor" href="#_6-3-记忆与技能的边界-知道什么与怎么做" aria-label="Permalink to &quot;6.3 记忆与技能的边界：知道什么与怎么做&quot;">​</a></h2><p><img src="`+p+`" alt="6.3 记忆与技能的边界：知道什么与怎么做" width="1600" height="1013" loading="lazy" decoding="async"></p><table tabindex="0"><thead><tr><th style="text-align:left;">记忆(周活降40%)</th><th style="text-align:left;">技能</th></tr></thead><tbody><tr><td style="text-align:left;">事实与偏好</td><td style="text-align:left;">流程与审批</td></tr></tbody></table><p>好流程<strong>指令存为技能</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>将我们用于此任务的流程保存为名为“每周账户健康状况”的技能。</span></span>
<span class="line"><span>包括源系统、风险定义、输出格式，以及联系客户始终需要批准这条规则。</span></span></code></pre></div><p><strong>屏幕演示</strong>三步走：</p><ol><li>对话开计算机视图</li><li>选「教会任务」输结果</li><li>屏幕演示</li></ol><p>限10分钟，不录麦克风与密码。@mvanhorn 提醒超10分钟易失败，拆成短阶段串联。<a href="https://jcng5q8n0f3z.feishu.cn/wiki/UGCCwisktiOC1Wk9adWcwN7env2" target="_blank" rel="noreferrer">fs46.md</a></p><p>Lauren Tan <strong>排错优先级</strong>：消除根源 &gt; 测试校验 &gt; 专有规则 &gt; 改记忆。团队技能由 Creator 或 Manager 发布，私聊只属个人。</p><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/FW0Ww6c4nivdMgkK7YncWmBent0" target="_blank" rel="noreferrer">fs57.md</a></p><h2 id="_6-4-团队记忆管理-写入协议、权限隔离与防冲突" tabindex="-1">6.4 团队记忆管理：写入协议、权限隔离与防冲突 <a class="header-anchor" href="#_6-4-团队记忆管理-写入协议、权限隔离与防冲突" aria-label="Permalink to &quot;6.4 团队记忆管理：写入协议、权限隔离与防冲突&quot;">​</a></h2><p>多人共用 Bot，<strong>一人教错会影响全员</strong>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>观察 (OBSERVE) -&gt; 分类 (CLASSIFY) -&gt; 核实 (VERIFY) -&gt; 晋升 (PROMOTE) -&gt; 重核 (RECHECK)</span></span></code></pre></div><p>写入记忆遵循五步：</p><ol><li><strong>观察</strong>：捕捉纠偏与新决策。</li><li><strong>分类</strong>：区分个人偏好与共用规则。</li><li><strong>核实</strong>：核对文档或代码，<strong>严禁口头推测入库</strong>。</li><li><strong>晋升</strong>：责任人确认后存入规则与权威链接。</li><li><strong>重核</strong>：重大操作前或到期后复验源头。</li></ol><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">claim</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;对外发布 API 变更前必须完成安全评审&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">scope</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;team&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">source</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://intranet.example/docs/launch-checklist&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">owner</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;security-team&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;approved&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">review_after</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-11-01&quot;</span></span></code></pre></div><p>外部卡片核对出处与负责人后，发指令入库。</p><p><strong>知识共享不等于权限共享</strong>：</p><ul><li><strong>个人 OAuth</strong>：调 Gmail 等插件走本人授权，不盗用权限。</li><li><strong>服务密钥</strong>：全员共享，<strong>遵循最小权限且通常只读</strong>。</li><li><strong>Slack 避坑</strong>：群内查私密数据会暴露给全员。公频只发汇总，<strong>敏感数据回私聊</strong>。</li></ul><p><strong>冲突裁决</strong>：<strong>立即暂停关键操作</strong> -&gt; 查权威源 -&gt; 责任人裁定 -&gt; 更新源头 -&gt; 修正记忆。</p><p><strong>排查坏记忆</strong>（如特批当常规）：</p><ol><li>查：让 Bot 列出记忆定位错误，溯源对话与任务。</li><li>改：先修源头文档，再发指令删改记忆。</li><li>验：<strong>换成员账号测试</strong>确认不拦截，纠偏历史工单。</li></ol><h2 id="_6-5-记忆备份与恢复-把云电脑当成可替换容器" tabindex="-1">6.5 记忆备份与恢复：把云电脑当成可替换容器 <a class="header-anchor" href="#_6-5-记忆备份与恢复-把云电脑当成可替换容器" aria-label="Permalink to &quot;6.5 记忆备份与恢复：把云电脑当成可替换容器&quot;">​</a></h2><p><img src="`+o+`" alt="6.5 记忆备份与恢复：把云电脑当成可替换容器" width="1600" height="1013" loading="lazy" decoding="async"></p><p>同账号所有 Bot 共用 <code>/workspace</code>（v0.68.1 分辨率 1920×1200）。</p><p><strong>云电脑随时会被官方重置</strong>（2026-10-10 曾发生过），装好的包和未提交状态全会清空，本地数据丢了找不回来，背景见 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/KUggwkhqqiRyxZkwTLhcrCU2ncg" target="_blank" rel="noreferrer">fs69.md</a>。</p><h3 id="备份流程与凭据安全" tabindex="-1">备份流程与凭据安全 <a class="header-anchor" href="#备份流程与凭据安全" aria-label="Permalink to &quot;备份流程与凭据安全&quot;">​</a></h3><p>建运维 Bot「记忆管家」，分四步备份到私有 Git。</p><ol><li>新建 Bot 命名为「记忆管家」，职责写明负责定期导出所有 Bot 的章程、规则与记忆。</li><li>在 <code>/workspace</code> 关联私有 Git 仓库，建好 <code>bots-backup/charters/</code>（指令）、<code>bots-backup/memories/</code>（规则）与 <code>environment/</code>（含脚本和 <code>services-ledger.md</code>）。</li><li>配每周定时 Routine，把配置与记忆存为 Markdown。</li><li><strong>由 Routine 自动跑 Git 命令提交并推送远端私有仓库</strong>。</li></ol><details class="details custom-block"><summary>备份流程与凭据安全</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/workspace/</span></span>
<span class="line"><span>└── bots-backup/</span></span>
<span class="line"><span>    ├── charters/          &lt;- 各 Bot 的长期规则 (如 researcher.md, writer.md)</span></span>
<span class="line"><span>    ├── memories/          &lt;- 团队共用决策与业务定义 (如 definitions.md)</span></span>
<span class="line"><span>    └── environment/</span></span>
<span class="line"><span>        ├── services-ledger.md  &lt;- 服务总账，记录工具依赖与启动命令</span></span>
<span class="line"><span>        └── restore.sh          &lt;- 虚拟机一键重置恢复脚本</span></span></code></pre></div></details><ul><li><strong>严禁把明文 Token 提交到 Git</strong>。自动化脚本只读本地 <code>~/.env</code> 取密钥。</li><li>遇到登录、两步验证或 CAPTCHA 时人工接管屏幕。Bot 只继承 Cookie，碰不到明文密码，详见 <a href="https://cursor.com/cn/docs/grok-bot/work" target="_blank" rel="noreferrer">使用 Grok Bot</a>。</li></ul><h2 id="_6-6-开箱即用的实战提示词" tabindex="-1">6.6 开箱即用的实战提示词 <a class="header-anchor" href="#_6-6-开箱即用的实战提示词" aria-label="Permalink to &quot;6.6 开箱即用的实战提示词&quot;">​</a></h2><h3 id="三层指令框架" tabindex="-1">三层指令框架 <a class="header-anchor" href="#三层指令框架" aria-label="Permalink to &quot;三层指令框架&quot;">​</a></h3><p>建 Bot 别写笼统简介，<strong>用三层框架明确规则、职责和当前聚焦</strong>。详见 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/UGCCwisktiOC1Wk9adWcwN7env2" target="_blank" rel="noreferrer">fs46.md</a>。</p><details class="details custom-block"><summary>三层指令框架</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BASE INSTRUCTIONS (基础规则，本账号所有 Bot 通用)</span></span>
<span class="line"><span>- 涉及产生财务支出、向外部发送任何信息、删除文件等操作前，必须等待人工确认。</span></span>
<span class="line"><span>- 当结论涉及重要业务决策时，必须调取当前权威来源进行核对，严禁单凭记忆作答。</span></span>
<span class="line"><span>- 若执行受阻，用单行明确说明受阻点，禁止擅自寻找不可靠的绕行方案。</span></span>
<span class="line"><span>- 阶段性工作交接结果统一写入 /workspace/shared/handoffs/ 目录。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ROLE (角色职责)</span></span>
<span class="line"><span>- 你的身份：每周账户健康状况审计专员。</span></span>
<span class="line"><span>- 你负责的固定作业：获取客户产品用量与工单信号，标记流失或扩张迹象。</span></span>
<span class="line"><span>- 验收标准：每项结论必须附带源系统监控图表或工单链接。</span></span>
<span class="line"><span>- 允许操作：读取日志、检索系统指标、在共享目录生成评估报告。</span></span>
<span class="line"><span>- 严禁操作：未经明确批准，绝不私自联络客户，绝不修改账户权限。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>CURRENT FOCUS (当前重点)</span></span>
<span class="line"><span>- 本周重点核查用量环比下降超过 30% 的企业级客户名单。</span></span></code></pre></div></details><h3 id="转为团队技能" tabindex="-1">转为团队技能 <a class="header-anchor" href="#转为团队技能" aria-label="Permalink to &quot;转为团队技能&quot;">​</a></h3><p>任务跑通后，直接<strong>发指令沉淀为技能</strong>。</p><details class="details custom-block"><summary>转为团队技能</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请将本次执行的工作流整理并保存为团队技能，名称设为“客户流失风险排查”。</span></span>
<span class="line"><span>要求包含以下内容：</span></span>
<span class="line"><span>1. 触发场景与必需的前置凭据。</span></span>
<span class="line"><span>2. 调取指标数据的具体步骤与判定阈值。</span></span>
<span class="line"><span>3. 输出结果的格式规范（必须包含数据源链接）。</span></span>
<span class="line"><span>4. 明确安全红线：向客户发送邮件或调整账户配置必须经由人工批准。</span></span>
<span class="line"><span>完成后在对话中回复技能概要。</span></span></code></pre></div></details><h3 id="写入共享记忆" tabindex="-1">写入共享记忆 <a class="header-anchor" href="#写入共享记忆" aria-label="Permalink to &quot;写入共享记忆&quot;">​</a></h3><p>负责人审批过的规则，<strong>带上来源和责任人写入</strong>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请为全团队记住以下判定规则：</span></span>
<span class="line"><span>对于所有对外发布的 API 变更，必须在发布前检查现行上线清单，并获取安全团队的正式签字评审。</span></span>
<span class="line"><span>若上线流程发生变更，以上线清单源文档为准，记忆仅作为指引。</span></span>
<span class="line"><span>来源文档：https://intranet.example/docs/api-checklist</span></span>
<span class="line"><span>责任人：security-team</span></span>
<span class="line"><span>复核日期：2026-11-01</span></span></code></pre></div><h3 id="部署记忆管家" tabindex="-1">部署记忆管家 <a class="header-anchor" href="#部署记忆管家" aria-label="Permalink to &quot;部署记忆管家&quot;">​</a></h3><p>在「记忆管家」Bot 里，<strong>发指令配好自动备份 Routine</strong>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是本账号的记忆管家。你的职责是定期归档全账号所有 Bot 的章程与共享记忆。</span></span>
<span class="line"><span>请配置一个每周运行的例行任务（Routine）：</span></span>
<span class="line"><span>1. 提取所有 Bot 当前的 Description/Instructions 规则，在 /workspace/bots-backup/charters/ 下按 Bot 名称分别保存为 .md 文件。</span></span>
<span class="line"><span>2. 提取当前所有已保存的团队共用记忆，整合保存为 /workspace/bots-backup/memories/team-memory.md。</span></span>
<span class="line"><span>3. 检查文件是否有更新。若有变更，自动执行 git add .、提交并推送至已配置好的私有 Git 仓库。</span></span>
<span class="line"><span>4. 若 Git 推送失败，在当前对话中告警并说明报错信息；若无变更则保持静默，不要频繁推送无意义通知。</span></span></code></pre></div><h3 id="坏记忆清理" tabindex="-1">坏记忆清理 <a class="header-anchor" href="#坏记忆清理" aria-label="Permalink to &quot;坏记忆清理&quot;">​</a></h3><p>发现引用了错误或旧规则，<strong>发指令直接纠偏清理</strong>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请检查并列出你当前记录的所有团队记忆中涉及“企业客户续约审批”的条目。</span></span>
<span class="line"><span>删除其中“所有企业客户续约必须经由 VP 逐笔批准”的内容。</span></span>
<span class="line"><span>该规则仅为上周特定情况下的临时特例，不是长期标准。</span></span>
<span class="line"><span>从现在起，企业客户续约标准重新以财务知识库的正式文档为准：https://intranet.example/finance/renewals</span></span>
<span class="line"><span>确认修改后，请向我展示修正后的相关记忆列表。</span></span></code></pre></div><h2 id="_6-7-经典案例复盘" tabindex="-1">6.7 经典案例复盘 <a class="header-anchor" href="#_6-7-经典案例复盘" aria-label="Permalink to &quot;6.7 经典案例复盘&quot;">​</a></h2><h3 id="案例-1-spacexai-数据分析-bot" tabindex="-1">案例 1：SpaceXAI 数据分析 Bot <a class="header-anchor" href="#案例-1-spacexai-数据分析-bot" aria-label="Permalink to &quot;案例 1：SpaceXAI 数据分析 Bot&quot;">​</a></h3><p>SpaceXAI 团队要查询 45,000 张表的超大数仓。</p><ul><li><strong>别把庞大数据硬塞进记忆</strong>。他们给 Bot 配置只读数仓凭证，把找表和查询沉淀为技能库。</li><li>记忆只保留指标口径和纠偏规则，变动数据靠实时调取计算。</li></ul><p>详见 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/FW0Ww6c4nivdMgkK7YncWmBent0" target="_blank" rel="noreferrer">fs57.md</a>。</p><h3 id="案例-2-多-bot-协作推文画像流水线" tabindex="-1">案例 2：多 Bot 协作推文画像流水线 <a class="header-anchor" href="#案例-2-多-bot-协作推文画像流水线" aria-label="Permalink to &quot;案例 2：多 Bot 协作推文画像流水线&quot;">​</a></h3><p>0xlangeai 搭建整理员、分析师、设计师、工程师四个 Bot 跑推文画像流水线。</p><ul><li>不同 Bot 无法读取彼此的聊天记录。</li><li><strong>跨 Bot 协作要靠文件系统传递成果</strong>。整理员生成 <code>tweets.md</code>，分析师读取后产出 <code>profile.md</code>，设计师据此出 <code>design.md</code>，工程师拉取代码构建上线。</li></ul><p>详见 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/KUggwkhqqiRyxZkwTLhcrCU2ncg" target="_blank" rel="noreferrer">fs69.md</a>。</p><h3 id="案例-3-jon-oneill-的管道派单系统" tabindex="-1">案例 3：Jon ONeill 的管道派单系统 <a class="header-anchor" href="#案例-3-jon-oneill-的管道派单系统" aria-label="Permalink to &quot;案例 3：Jon ONeill 的管道派单系统&quot;">​</a></h3><p>Jon ONeill 自动化处理跨 Gmail、Slack、ServiceTitan 和客户门户的工单排期。</p><ul><li>单个全能调度 Bot 承担所有规则容易混乱出错，最终只能停用。</li><li>任务切分给专职 Bot：Gary 盯 Gmail，Steve 查 ServiceTitan 工期，Quinn 发短信，Sarah 对接 Slack 员工，Atlas 统筹。</li><li><strong>拆细职责后每天稳定处理 5 到 6 个紧急工单，10 分钟内完成全流程排期</strong>。</li></ul><p>详见 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/UGCCwisktiOC1Wk9adWcwN7env2" target="_blank" rel="noreferrer">fs46.md</a>。</p><h2 id="_6-8-容易踩的坑" tabindex="-1">6.8 容易踩的坑 <a class="header-anchor" href="#_6-8-容易踩的坑" aria-label="Permalink to &quot;6.8 容易踩的坑&quot;">​</a></h2><ul><li><strong>变动数据走实时查询</strong>：库存别存记忆，防 Bot 拿旧数据误判。</li><li><strong>配置必写脚本</strong>：云电脑手动配置，重置全归零。</li><li><strong>私聊指令别全队用</strong>：特批直接共用会污染团队行为。</li><li><strong>分 Bot 做不了隔离</strong>：同账号共享文件，靠权限与 Ask-first 审批。</li><li><strong>密码别发聊天框</strong>：防日志泄露，走安全凭据或人工接管。</li><li><strong>Slack 别查私密数据</strong>：公开频道提问，容易把隐私打在公屏。</li></ul><h2 id="_6-9-做完怎么验收" tabindex="-1">6.9 做完怎么验收 <a class="header-anchor" href="#_6-9-做完怎么验收" aria-label="Permalink to &quot;6.9 做完怎么验收&quot;">​</a></h2><p>测记忆边界直接跑社区作者 rari（@0xwhrrari）设计的 M01-M05 用例。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>M01 个人偏好隔离测试 -&gt; 成员 A 在私聊中设定个性化偏好，使用成员 B 账号发起提问，确认 B 绝不继承 A 的私聊偏好。</span></span>
<span class="line"><span>M02 团队规则晋升测试 -&gt; 成员 A 提交一条经审批的团队规则并写入团队记忆，成员 B 发起任务时应生效该规则，但看不到 A 当时的私聊对话。</span></span>
<span class="line"><span>M03 状态时效回源测试 -&gt; 在团队记忆中保留一条旧状态，在源系统修改为新状态。向 Bot 提问，Bot 必须调取最新源数据，而不是采信记忆中的旧状态。</span></span>
<span class="line"><span>M04 冲突自动阻断测试 -&gt; 两个成员分别向 Bot 给出互相矛盾的业务说法。Bot 应识别出冲突并主动停止高风险操作，指出需要责任人裁决，而不是悄悄采纳最后一条说法。</span></span>
<span class="line"><span>M05 共享渠道边界测试 -&gt; 在 Slack 共享频道线程中，要求 Bot 调用某成员的个人连接器。Bot 必须正确发起审批，且回复内容只包含团队可见的脱敏结论。</span></span></code></pre></div><p>这里<strong>必须用两个不同的真实团队账号交叉测</strong>，单个账号测不出隔离边界。</p><ol><li>登录 GitHub 或 GitLab 私有库，确认 <code>bots-backup/charters/</code> 下各 Bot 的规则文件已提交，规则与权限没丢。</li><li>检查 <code>bots-backup/memories/team-memory.md</code>，确认团队判定规则与源系统链接完整。</li><li>在云电脑测试目录跑环境恢复脚本，<strong>确认依赖与目录无报错，单行脚本能直接拉起服务</strong>。</li></ol><details class="details custom-block"><summary>6.9 做完怎么验收</summary><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">   bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /workspace/bots-backup/environment/restore.sh</span></span></code></pre></div><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>官方文档：<a href="https://cursor.com/cn/docs/grok-bot/work" target="_blank" rel="noreferrer">使用 Grok Bot</a></li><li>社区文章：rari《Grok Bot Memory Engineering: How One Agent Learns With a Team》 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/FW0Ww6c4nivdMgkK7YncWmBent0" target="_blank" rel="noreferrer">fs57.md</a></li><li>社区文章：《4.6 虚拟机、记忆与备份》 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/KUggwkhqqiRyxZkwTLhcrCU2ncg" target="_blank" rel="noreferrer">fs69.md</a></li><li>社区文章：Matt Van Horn《Every Grok Bot Hack I Know (Aug 2026)》 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/UGCCwisktiOC1Wk9adWcwN7env2" target="_blank" rel="noreferrer">fs46.md</a></li></ul></details>`,88)])])}const f=s(r,[["render",c]]);export{m as __pageData,f as default};
